CREATE TABLE IF NOT EXISTS zukan_trust_anchors ( trust_anchor_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL, anchor_method TEXT NOT NULL, anchor_subject_id UUID REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, assurance_level INTEGER NOT NULL DEFAULT 1, evidence_content_object_id UUID REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, valid_from TIMESTAMPTZ NOT NULL, valid_to TIMESTAMPTZ, policy_version TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (anchor_method IN ('official_domain', 'government_register', 'signed_agreement', 'authenticated_account', 'manual_institutional_review')), CHECK (assurance_level BETWEEN 1 AND 5), CHECK (valid_to IS NULL OR valid_to > valid_from) ); CREATE TABLE IF NOT EXISTS zukan_authority_assertions ( authority_assertion_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), authority_subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, trust_anchor_id UUID NOT NULL REFERENCES zukan_trust_anchors(trust_anchor_id) ON DELETE RESTRICT, predicate_uri TEXT, predicate_version INTEGER, subject_scope JSONB NOT NULL DEFAULT '{}'::jsonb, jurisdiction TEXT, authority_rank INTEGER NOT NULL DEFAULT 0, valid_from TIMESTAMPTZ NOT NULL, valid_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (authority_rank >= 0), CHECK (valid_to IS NULL OR valid_to > valid_from), CHECK ((predicate_uri IS NULL AND predicate_version IS NULL) OR (predicate_uri IS NOT NULL AND predicate_version IS NOT NULL)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_authority_assertions_scope ON zukan_authority_assertions (authority_subject_id, predicate_uri, predicate_version, valid_from DESC); CREATE TABLE IF NOT EXISTS zukan_authority_revocation_events ( authority_revocation_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), authority_assertion_id UUID NOT NULL REFERENCES zukan_authority_assertions(authority_assertion_id) ON DELETE RESTRICT, revocation_mode TEXT NOT NULL, effective_at TIMESTAMPTZ NOT NULL, reason TEXT NOT NULL, impact_manifest JSONB NOT NULL DEFAULT '{}'::jsonb, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (revocation_mode IN ('prospective', 'retroactive')) ); DROP TRIGGER IF EXISTS trg_zukan_authority_revocations_no_update ON zukan_authority_revocation_events; CREATE TRIGGER trg_zukan_authority_revocations_no_update BEFORE UPDATE OR DELETE ON zukan_authority_revocation_events FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); CREATE TABLE IF NOT EXISTS zukan_claim_authority_links ( claim_revision_id UUID NOT NULL REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, authority_assertion_id UUID NOT NULL REFERENCES zukan_authority_assertions(authority_assertion_id) ON DELETE RESTRICT, PRIMARY KEY (claim_revision_id, authority_assertion_id) ); CREATE TABLE IF NOT EXISTS zukan_resolution_policy_versions ( policy_id TEXT NOT NULL, policy_version INTEGER NOT NULL, policy_definition JSONB NOT NULL, evaluator_contract_version TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (policy_id, policy_version), CHECK (policy_version >= 1) ); DROP TRIGGER IF EXISTS trg_zukan_resolution_policies_no_update ON zukan_resolution_policy_versions; CREATE TRIGGER trg_zukan_resolution_policies_no_update BEFORE UPDATE OR DELETE ON zukan_resolution_policy_versions FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); CREATE TABLE IF NOT EXISTS zukan_resolution_runs ( resolution_run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL, workspace_id TEXT, subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, candidate_query_id TEXT NOT NULL, candidate_query_version INTEGER NOT NULL, claim_store_snapshot_token TEXT NOT NULL, claim_store_sequence_watermark BIGINT NOT NULL, recorded_time_watermark TIMESTAMPTZ NOT NULL, predicate_registry_snapshot_hash TEXT NOT NULL, authority_snapshot_hash TEXT NOT NULL, policy_id TEXT NOT NULL, policy_version INTEGER NOT NULL, evaluator_build TEXT NOT NULL, target_time TIMESTAMPTZ, execution_context JSONB NOT NULL DEFAULT '{}'::jsonb, resolution_status TEXT NOT NULL, input_hash TEXT NOT NULL, output_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (candidate_query_version >= 1), CHECK (claim_store_sequence_watermark >= 0), CHECK (resolution_status IN ('empty', 'resolved', 'disputed', 'manual_review')), CHECK (predicate_registry_snapshot_hash ~ '^[0-9a-f]{64}$'), CHECK (authority_snapshot_hash ~ '^[0-9a-f]{64}$'), CHECK (input_hash ~ '^[0-9a-f]{64}$'), CHECK (output_hash ~ '^[0-9a-f]{64}$'), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT, FOREIGN KEY (policy_id, policy_version) REFERENCES zukan_resolution_policy_versions(policy_id, policy_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_resolution_runs_subject ON zukan_resolution_runs (subject_id, predicate_uri, predicate_version, created_at DESC); CREATE INDEX IF NOT EXISTS idx_zukan_resolution_runs_watermark ON zukan_resolution_runs (claim_store_sequence_watermark, recorded_time_watermark); CREATE TABLE IF NOT EXISTS zukan_resolution_run_claims ( resolution_run_id UUID NOT NULL REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE RESTRICT, claim_revision_id UUID NOT NULL REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, candidate_ordinal INTEGER NOT NULL, decision TEXT NOT NULL, reason_codes JSONB NOT NULL DEFAULT '[]'::jsonb, PRIMARY KEY (resolution_run_id, claim_revision_id), CHECK (candidate_ordinal >= 0), CHECK (decision IN ('accepted', 'rejected', 'tied', 'ineligible')), CHECK (jsonb_typeof(reason_codes) = 'array') ); CREATE TABLE IF NOT EXISTS zukan_projection_snapshots ( projection_snapshot_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), resolution_run_id UUID NOT NULL REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE RESTRICT, snapshot_hash TEXT NOT NULL UNIQUE, reproducibility_at_issue TEXT NOT NULL DEFAULT 'full', context JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (snapshot_hash ~ '^[0-9a-f]{64}$'), CHECK (reproducibility_at_issue IN ('full', 'redacted', 'degraded')) ); CREATE TABLE IF NOT EXISTS zukan_projection_entries ( projection_snapshot_id UUID NOT NULL REFERENCES zukan_projection_snapshots(projection_snapshot_id) ON DELETE RESTRICT, entry_key TEXT NOT NULL, claim_revision_id UUID REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, value_artifact_id UUID REFERENCES zukan_value_artifacts(artifact_id) ON DELETE RESTRICT, entry_payload JSONB NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY (projection_snapshot_id, entry_key) ); CREATE TABLE IF NOT EXISTS zukan_publication_editions ( publication_edition_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), publication_key TEXT NOT NULL, edition_label TEXT NOT NULL, projection_snapshot_id UUID NOT NULL REFERENCES zukan_projection_snapshots(projection_snapshot_id) ON DELETE RESTRICT, manifest_hash TEXT NOT NULL UNIQUE, manifest_payload JSONB NOT NULL DEFAULT '{}'::jsonb, issued_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (manifest_hash ~ '^[0-9a-f]{64}$') ); CREATE INDEX IF NOT EXISTS idx_zukan_publication_editions_key ON zukan_publication_editions (publication_key, issued_at DESC); DROP TRIGGER IF EXISTS trg_zukan_resolution_runs_no_update ON zukan_resolution_runs; CREATE TRIGGER trg_zukan_resolution_runs_no_update BEFORE UPDATE OR DELETE ON zukan_resolution_runs FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_resolution_run_claims_no_update ON zukan_resolution_run_claims; CREATE TRIGGER trg_zukan_resolution_run_claims_no_update BEFORE UPDATE OR DELETE ON zukan_resolution_run_claims FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_projection_snapshots_no_update ON zukan_projection_snapshots; CREATE TRIGGER trg_zukan_projection_snapshots_no_update BEFORE UPDATE OR DELETE ON zukan_projection_snapshots FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_projection_entries_no_update ON zukan_projection_entries; CREATE TRIGGER trg_zukan_projection_entries_no_update BEFORE UPDATE OR DELETE ON zukan_projection_entries FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); DROP TRIGGER IF EXISTS trg_zukan_publication_editions_no_update ON zukan_publication_editions; CREATE TRIGGER trg_zukan_publication_editions_no_update BEFORE UPDATE OR DELETE ON zukan_publication_editions FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation();
